    // Position 1
    _modifyPosition(ModifyPositionParams({
        owner: msg.sender,
        tickLower: 100,
        tickUpper: 200,
        liquidityDelta: 1000
    })); // Triggers 2 separate tick updates

    // Position 2
    _modifyPosition(ModifyPositionParams({
        owner: msg.sender,
        tickLower: 150,
        tickUpper: 250,
        liquidityDelta: 1000
