And the same on all other functions, even if they are making transfers.

Several other contracts also do not issue events in important functions.

Like all functions in `V3SwapRouter`, for example:

```Solidity
function katanaV3SwapCallback(int256 amount0Delta, int256 amount1Delta, bytes calldata data) external {
    if (amount0Delta <= 0 && amount1Delta <= 0) revert V3InvalidSwap(); // swaps entirely within 0-liquidity regions are not supported
    (, address payer) = abi.decode(data, (bytes, address));
    bytes calldata path = data.toBytes(0);

    // because exact output swaps are executed in reverse order, in this case tokenOut is actually tokenIn
    (address tokenIn, uint24 fee, address tokenOut) = path.decodeFirstPool();

    if (computePoolAddress(tokenIn, tokenOut, fee) != msg.sender) revert V3InvalidCaller();

    (bool isExactInput, uint256 amountToPay) =
      amount0Delta > 0 ? (tokenIn < tokenOut, uint256(amount0Delta)) : (tokenOut < tokenIn, uint256(amount1Delta));

    if (isExactInput) {
      // Pay the pool (msg.sender)
      payOrPermit2Transfer(tokenIn, payer, msg.sender, amountToPay);
    } else {
      // either initiate the next swap or pay
      if (path.hasMultiplePools()) {
        // this is an intermediate step so the payer is actually this contract
        path = path.skipToken();
        _swap(-amountToPay.toInt256(), msg.sender, path, payer, false);
      } else {
        if (amountToPay > maxAmountInCached) revert V3TooMuchRequested();
        // note that because exact output swaps are executed in reverse order, tokenOut is actually tokenIn
        payOrPermit2Transfer(tokenOut, payer, msg.sender, amountToPay);
      }
    }
  }
```

Or all functions in `Permit2Payments` that directly transfers values.

